function numberRarity(score){const q=CFG.scoreQuantiles;if(score>=q['0.99'])return['Mythic','Top 1%'];if(score>=q['0.95'])return['Anomaly','Top 5–1%'];if(score>=q['0.9'])return['Epic','Top 10–5%'];if(score>=q['0.75'])return['Rare','Top 25–10%'];if(score>=q['0.5'])return['Uncommon','Top 50–25%'];if(score<=q['0.01'])return['Trash','Bottom 1%'];return['Common','Bottom 50%']}
