function jackpotInfo(score){const rank=exactTopRank(score);if(rank&&rank<=100)return{tier:'ULTRA JACKPOT',detail:'Top 0.01%',ultra:true,rank};if(rank&&rank<=1000)return{tier:'JACKPOT',detail:'Top 0.1%',ultra:false,rank};return null}

function factorize(n){if(n<2)return[];let x=n,out=[];for(let p=2;p*p<=x;p+=(p===2?1:2)){if(x%p===0){let e=0;while(x%p===0){x/=p;e++}out.push([p,e])}}if(x>1)out.push([x,1]);return out}
