function witnessHue(b){const f=String(b?.family||''),c=String(b?.cat||'').toLowerCase();if(b?.src==='x'){if(/prime_halves|prime_chunks|reverse_prime/.test(f))return 282;if(/square|cube|triangular|pentagonal|hexagonal|heptagonal|octagonal/.test(f))return 326;if(/chunks/.test(f))return 198;if(/reverse/.test(f))return 158;if(/fibonacci|lucas/.test(f))return 42;if(/halves/.test(f))return 18;let h=0;for(const ch of f)h=(Math.imul(h,31)+ch.charCodeAt(0))>>>0;return h%360}if(/digit|base|decimal|binary/.test(f+c))return 207;if(/prime|pseudoprime|reptend/.test(f+c))return 278;if(/geometry|figurate|polygon|grassmann|projective/.test(f+c))return 326;if(/combin|partition|sequence|_value|leyland/.test(f+c))return 36;if(/algebra|field|residue|cyclotomic|modular|totient|mobius/.test(f+c))return 175;if(/graph|tree/.test(f+c))return 145;return 225}
