function mathHTML(text,roles){const re=/(\b\d+(?:\.\d+)?\b|(?:F|P|C|S|B|ord|mod|gcd|lcm|phi|sigma|tau|mu|omega)(?:_?\d+)?|[φτσμωΩ]|[=+×÷−±<>≤≥≡→|·²³^/]+)/g;let out='',last=0,m;while((m=re.exec(String(text)))){out+=esc(text.slice(last,m.index));const t=m[0];let cl='math-op';if(/^\d/.test(t))cl='math-'+(roles?.get(t)||'value');else if(/^(?:F|P|C|S|B|ord|mod|gcd|lcm|phi|sigma|tau|mu|omega|[φτσμωΩ])/.test(t))cl='math-fn';out+=`<span class="${cl}">${esc(t)}</span>`;last=m.index+t.length}return out+esc(String(text).slice(last))}
function splitPreviewHTML(b,n){const f=String(b?.family||''),raw=String(n);if(isDecimalHalfFamily(b)&&raw.length>=2&&raw.length%2===0){const h=raw.length/2;return`<div class="number-split"><span class="split-part role-a">${esc(raw.slice(0,h))}</span><span class="split-bar">|</span><span class="split-part role-b">${esc(raw.slice(h))}</span></div>`}if(/chunks|two_digit|three_two_digit/.test(f)&&raw.length===6)return`<div class="number-split chunks"><span class="split-part role-a">${esc(raw.slice(0,2))}</span><span class="split-bar">|</span><span class="split-part role-b">${esc(raw.slice(2,4))}</span><span class="split-bar">|</span><span class="split-part role-c">${esc(raw.slice(4))}</span></div>`;return''}
